<template><BaseModal v-model="visible" size="sm" :close-disabled="loading" :close-on-esc="!loading" :close-on-overlay-click="!loading"><template #header><div class="title"><h2>{{category?'ویرایش دسته‌بندی':'دسته‌بندی جدید'}}</h2><p v-if="category">{{category.name}}</p></div></template><form id="category-form" dir="rtl" novalidate @submit.prevent="submit"><div v-if="serverError" class="error" role="alert">{{serverError}}</div><label>نام دسته‌بندی <b>الزامی</b><input ref="nameInput" v-model.trim="form.name" maxlength="100" placeholder="مثلاً مواد اولیه" required/><em v-if="errors.name">{{errors.name}}</em></label><label>کد گزارش‌گیری <b>اختیاری</b><input v-model.trim="form.code" maxlength="50" dir="ltr" placeholder="raw-materials"/><em v-if="errors.code">{{errors.code}}</em></label><label class="active"><span><strong>دسته‌بندی فعال باشد</strong><small>دسته فعال هنگام ثبت هزینه قابل انتخاب است.</small></span><input v-model="form.is_active" type="checkbox"/></label></form><template #footer><button class="secondary" :disabled="loading" @click="visible=false">انصراف</button><button class="primary" form="category-form" :disabled="loading">{{loading?'در حال ذخیره…':category?'ذخیره تغییرات':'ایجاد دسته‌بندی'}}</button></template></BaseModal></template>
<script setup>
import { computed,nextTick,reactive,ref,watch } from 'vue';import BaseModal from '@/components/modals/BaseModal.vue'
const props=defineProps({modelValue:Boolean,category:{type:Object,default:null},loading:Boolean,serverError:{type:String,default:''},fieldErrors:{type:Object,default:()=>({})}}),emit=defineEmits(['update:modelValue','submit']),visible=computed({get:()=>props.modelValue,set:value=>emit('update:modelValue',value)}),form=reactive({name:'',code:'',is_active:true}),errors=reactive({}),nameInput=ref(null)
function clear(){Object.keys(errors).forEach(key=>delete errors[key])}function hydrate(){clear();Object.assign(form,{name:props.category?.name||'',code:props.category?.code||'',is_active:props.category?.is_active??true});if(props.modelValue)nextTick(()=>nameInput.value?.focus())}function submit(){clear();if(!form.name)errors.name='نام دسته‌بندی را وارد کنید.';if(!Object.keys(errors).length)emit('submit',{...form,code:form.code||null})}watch(()=>[props.modelValue,props.category],hydrate,{immediate:true,deep:true});watch(()=>props.fieldErrors,value=>{clear();for(const [key,messages] of Object.entries(value||{}))errors[key]=Array.isArray(messages)?messages[0]:messages},{deep:true})
</script>
<style scoped>.title h2,.title p{margin:0}.title h2{font-size:1.15rem}.title p{margin-top:3px;color:var(--muted);font-size:.72rem}form{display:grid;gap:15px}label{display:grid;gap:6px;font-size:.78rem;font-weight:700}label>b{color:var(--muted);font-size:.64rem;font-weight:400}input{width:100%;min-height:43px;padding:9px 11px;border:1px solid var(--border-strong);border-radius:9px;background:var(--input);color:var(--text);font:inherit;box-sizing:border-box}input:focus{outline:3px solid var(--focus);border-color:var(--primary)}em{color:var(--danger);font-size:.7rem;font-style:normal}.active{display:flex;align-items:center;justify-content:space-between;padding:12px;border:1px solid var(--border);border-radius:9px}.active span{display:grid;gap:3px}.active small{color:var(--muted);font-size:.65rem;font-weight:400}.active input{width:20px;min-height:20px;accent-color:var(--primary)}.error{padding:10px;border:1px solid #fecaca;border-radius:8px;background:#fef2f2;color:var(--danger);font-size:.74rem}.primary,.secondary{min-width:110px;padding:10px 14px;border:0;border-radius:9px;font:inherit;font-weight:700}.primary{background:var(--primary);color:#fff}.secondary{background:var(--surface-subtle);color:var(--text)}</style>
